"""Model-based differential test: in-memory spec model vs RequestStore."""
import os, random, sys, tempfile, time
sys.path.insert(0, "src")
from forgetting_evidence.requests import RequestStore, _utc_now_rfc3339

random.seed(987654321)
tmp = tempfile.mkdtemp()

class Model:
    """Independent in-memory model of the reconcile/batch spec."""
    def __init__(self):
        self.reqs = {}  # rid -> dict(status, created_at, attempts=[], token)
        self.order = []  # (created_at, rid) insertion order
        self.batches = {}  # batch_id -> dict(pos_idx, finished, items)

    def submit(self, rid, created_at):
        self.reqs[rid] = dict(status="accepted", created_at=created_at,
                              attempts=[], token=object())
        self.reqs[rid]["token"] = None
        self.order.append(rid)

    def _sorted(self):
        return sorted(self.order, key=lambda r: (self.reqs[r]["created_at"], r))

    def claim_next(self, now, lease_secs):
        expiry = now + lease_secs  # seconds float model
        for rid in self._sorted():
            r = self.reqs[rid]
            if r["status"] == "accepted":
                ok = True
            elif r["status"] == "processing":
                if not r["attempts"]:
                    continue
                latest = r["attempts"][-1]
                if not (now > latest["expiry"]):
                    continue
                if latest["result"] is not None:
                    continue
                if any(a["result"] is None and now <= a["expiry"] for a in r["attempts"]):
                    continue
                ok = True
            else:
                continue
            if ok:
                r["attempts"].append(dict(expiry=expiry, result=None, completed_at=None))
                r["token"] = object()
                if r["status"] == "accepted":
                    r["status"] = "processing"
                return rid, r["token"]
        return None

    def finish(self, rid, token, result, now):
        r = self.reqs[rid]
        if r["token"] is None or r["token"] is not token:
            return "conflict"
        attempt = r["attempts"][-1]
        if attempt["result"] is not None or now > attempt["expiry"]:
            return "conflict"
        if r["status"] != "processing":
            return "conflict"
        r["status"] = result
        attempt["result"] = result
        attempt["completed_at"] = now
        r["token"] = None
        return "ok"

    def reconcile(self, rid, now):
        r = self.reqs[rid]
        if r["status"] == "accepted":
            return r["status"]
        if r["status"] in ("completed", "failed"):
            self._normalise(r)
            return r["status"]
        # processing
        live = any(a["result"] is None and now <= a["expiry"] for a in r["attempts"])
        if live:
            return "processing"
        terminals = [(a["completed_at"], i, a["result"])
                     for i, a in enumerate(r["attempts"]) if a["result"] is not None]
        target = min(terminals)[2] if terminals else "failed"
        r["status"] = target
        for a in r["attempts"]:
            if a["result"] is None:
                a["result"] = "failed"
                a["completed_at"] = now
        if terminals:
            win = min(terminals)[1]
            for i, a in enumerate(r["attempts"]):
                if i != win and a["result"] == "completed":
                    a["result"] = "failed"
        r["token"] = None
        return target

    def _normalise(self, r):
        terminals = [(a["completed_at"], i) for i, a in enumerate(r["attempts"])
                     if a["result"] is not None]
        if not terminals:
            return
        win = min(terminals)[1]
        for i, a in enumerate(r["attempts"]):
            if i != win and a["result"] == "completed":
                a["result"] = "failed"


# Differential run: single-request reconcile + claim/finish only (batch needs
# position modelling; checked separately below).
fails = 0
for trial in range(30):
    store = RequestStore(os.path.join(tmp, f"m{trial}.db"))
    model = Model()
    clock = [1_000_000.0]  # model clock in seconds
    rid_tokens = {}
    rids = []
    for step in range(40):
        op = random.choice(["submit", "claim", "finish", "reconcile", "sleep", "reconcile"])
        if op == "submit" or not rids:
            rec = store.submit("t", f"s{step}", ["email"], f"k{trial}-{step}")
            rid = rec["request_id"]
            rids.append(rid)
            model.submit(rid, rec["created_at"])
            continue
        if op == "sleep":
            dt = random.choice([0.05, 0.4, 1.2])
            clock[0] += dt
            time.sleep(dt)
            continue
        if op == "claim":
            lease = random.choice([1, 2, 3600])
            got = store.claim_next("t", "w", lease)
            want = model.claim_next(clock[0], lease)
            if (got is None) != (want is None):
                print(f"MISMATCH claim t{trial} s{step}: store={got} model={want}")
                fails += 1
            elif got is not None:
                if got["request_id"] != want[0]:
                    print(f"MISMATCH claim rid t{trial} s{step}: {got['request_id']} vs {want[0]}")
                    fails += 1
                rid_tokens[got["request_id"]] = (got["claim_token"], want[1])
            continue
        if op == "finish":
            rid = random.choice(rids)
            if rid in rid_tokens:
                tok, mtok = rid_tokens.pop(rid)
                result = random.choice(["completed", "failed"])
                try:
                    out = store.finish_claim("t", rid, tok, result)
                    got = ("ok", out["status"])
                except Exception as e:
                    got = ("conflict", type(e).__name__)
                want = model.finish(rid, mtok, result, clock[0])
                if (got[0] == "ok") != (want == "ok"):
                    print(f"MISMATCH finish t{trial} s{step}: store={got} model={want}")
                    fails += 1
            continue
        if op == "reconcile":
            rid = random.choice(rids)
            out = store.reconcile_execution("t", rid)
            want = model.reconcile(rid, clock[0])
            if out["status"] != want:
                print(f"MISMATCH reconcile t{trial} s{step} rid={rid}: store={out['status']} model={want}")
                fails += 1
            continue
    # final full reconcile-all and compare
    for rid in rids:
        out = store.reconcile_execution("t", rid)
        want = model.reconcile(rid, clock[0])
        if out["status"] != want:
            print(f"FINAL MISMATCH t{trial} rid={rid}: store={out['status']} model={want}")
            fails += 1
        log = store.get_execution_log("t", rid)
        matt = model.reqs[rid]["attempts"]
        if len(log) != len(matt):
            print(f"FINAL MISMATCH attempts len t{trial} rid={rid}")
            fails += 1
        else:
            for entry, ma in zip(log, matt):
                if (entry["result"] is None) != (ma["result"] is None):
                    print(f"FINAL MISMATCH attempt result t{trial} rid={rid}: {entry} vs {ma}")
                    fails += 1
                elif entry["result"] != ma["result"]:
                    print(f"FINAL MISMATCH attempt result value t{trial} rid={rid}: {entry['result']} vs {ma['result']}")
                    fails += 1

print("FAILS:", fails)

