"""Differential test v2: model mirrors store-returned timestamps exactly."""
import os, random, sys, tempfile, time
from datetime import datetime, timezone
sys.path.insert(0, "src")
from forgetting_evidence.requests import RequestStore

random.seed(1122334455)
tmp = tempfile.mkdtemp()

def parse(ts):
    return datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()

class Model:
    def __init__(self):
        self.reqs = {}  # rid -> dict(status, created_at, attempts, token)
        self.order = []

    def submit(self, rid, created_at):
        self.reqs[rid] = dict(status="accepted", created_at=created_at,
                              attempts=[], token=None)
        self.order.append(rid)

    def _sorted(self):
        return sorted(self.order, key=lambda r: (self.reqs[r]["created_at"], r))

    def claimable(self, rid, now):
        r = self.reqs[rid]
        if r["status"] == "accepted":
            return True
        if r["status"] != "processing":
            return False
        if not r["attempts"]:
            return False
        latest = r["attempts"][-1]
        if not (now > latest["expiry"]):
            return False
        if latest["result"] is not None:
            return False
        if any(a["result"] is None and now <= a["expiry"] for a in r["attempts"]):
            return False
        return True

    def claim_next(self, now):
        for rid in self._sorted():
            if self.claimable(rid, now):
                return rid
        return None

    def reconcile(self, rid, now):
        r = self.reqs[rid]
        if r["status"] == "accepted":
            return "accepted"
        if r["status"] in ("completed", "failed"):
            self._normalise(r)
            return r["status"]
        live = any(a["result"] is None and now <= a["expiry"] for a in r["attempts"])
        if live:
            return "processing"
        terminals = [(a["completed_at"], i, a["result"])
                     for i, a in enumerate(r["attempts"]) if a["result"] is not None]
        target = min(terminals)[2] if terminals else "failed"
        r["status"] = target
        for a in r["attempts"]:
            if a["result"] is None:
                a["result"] = "failed"
                a["completed_at"] = now
        if terminals:
            win = min(terminals)[1]
            for i, a in enumerate(r["attempts"]):
                if i != win and a["result"] == "completed":
                    a["result"] = "failed"
        r["token"] = None
        return target

    def _normalise(self, r):
        terminals = [(a["completed_at"], i) for i, a in enumerate(r["attempts"])
                     if a["result"] is not None]
        if not terminals:
            return
        win = min(terminals)[1]
        for i, a in enumerate(r["attempts"]):
            if i != win and a["result"] == "completed":
                a["result"] = "failed"


fails = 0
skips = 0
for trial in range(25):
    store = RequestStore(os.path.join(tmp, f"m{trial}.db"))
    model = Model()
    tokens = {}
    rids = []
    for step in range(50):
        op = random.choice(["submit", "claim", "claim", "finish", "reconcile",
                            "reconcile", "sleep"])
        if op == "submit" or not rids:
            rec = store.submit("t", f"s{step}", ["email"], f"k{trial}-{step}")
            rids.append(rec["request_id"])
            model.submit(rec["request_id"], rec["created_at"])
        elif op == "sleep":
            time.sleep(random.choice([0.05, 0.3, 0.9]))
        elif op == "claim":
            lease = random.choice([1, 3600])
            before = time.time()
            got = store.claim_next("t", "w", lease)
            after = time.time()
            want = model.claim_next(before)
            if got is None and want is None:
                pass
            elif got is not None and want is not None and got["request_id"] == want:
                rid = got["request_id"]
                model.reqs[rid]["attempts"].append(
                    dict(expiry=parse(got["lease_expires_at"]), result=None,
                         completed_at=None))
                tok = object()
                model.reqs[rid]["token"] = tok
                if model.reqs[rid]["status"] == "accepted":
                    model.reqs[rid]["status"] = "processing"
                tokens[rid] = (got["claim_token"], tok)
            else:
                # Boundary race forgiveness: recompute model choice at `after`;
                # if either boundary time agrees with the store, skip.
                want2 = model.claim_next(after)
                got_rid = got["request_id"] if got else None
                if got_rid == want or got_rid == want2 or want in (got_rid,) or want2 in (got_rid,):
                    skips += 1
                    # still mirror reality if the store claimed
                    if got is not None:
                        rid = got["request_id"]
                        model.reqs[rid]["attempts"].append(
                            dict(expiry=parse(got["lease_expires_at"]), result=None,
                                 completed_at=None))
                        tok = object()
                        model.reqs[rid]["token"] = tok
                        if model.reqs[rid]["status"] == "accepted":
                            model.reqs[rid]["status"] = "processing"
                        tokens[rid] = (got["claim_token"], tok)
                else:
                    print(f"MISMATCH claim t{trial}s{step}: store={got_rid} model={want}/{want2}")
                    fails += 1
        elif op == "finish":
            rid = random.choice(rids)
            if rid not in tokens:
                continue
            tok, mtok = tokens.pop(rid)
            result = random.choice(["completed", "failed"])
            before = time.time()
            try:
                out = store.finish_claim("t", rid, tok, result)
                got = "ok"
            except Exception:
                got = "conflict"
            after = time.time()
            r = model.reqs[rid]
            live_at = lambda t: (r["token"] is mtok and r["attempts"] and
                                 r["attempts"][-1]["result"] is None and
                                 not (t > r["attempts"][-1]["expiry"]) and
                                 r["status"] == "processing")
            m_before, m_after = live_at(before), live_at(after)
            if got == "ok":
                if not (m_before or m_after):
                    print(f"MISMATCH finish t{trial}s{step}: store ok, model conflict")
                    fails += 1
                r["status"] = result
                r["attempts"][-1]["result"] = result
                r["attempts"][-1]["completed_at"] = after
                r["token"] = None
            else:
                if m_before and m_after:
                    print(f"MISMATCH finish t{trial}s{step}: store conflict, model ok")
                    fails += 1
                else:
                    skips += 1
        elif op == "reconcile":
            rid = random.choice(rids)
            before = time.time()
            out = store.reconcile_execution("t", rid)
            after = time.time()
            m1 = model.reconcile(rid, before)
            if out["status"] != m1:
                # boundary race: recompute with `after` on a fresh copy is
                # complex; instead check if the request sits within 0.2s of a
                # lease boundary, else report.
                r = model.reqs[rid]
                near = any(a["result"] is None and abs(a["expiry"] - before) < 0.5
                           for a in r["attempts"])
                if near:
                    skips += 1
                    # resync model status to store's report
                    r["status"] = out["status"]
                else:
                    print(f"MISMATCH reconcile t{trial}s{step} rid={rid[-8:]}: "
                          f"store={out['status']} model={m1}")
