def parse(ts):
    return datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()

class Model:
    def __init__(self):
        self.reqs = {}
        self.order = []
        self.batches = {}
        self.nb = 0

    def submit(self, rid, created_at):
        self.reqs[rid] = dict(status="accepted", created_at=created_at,
                              attempts=[], token=None)
        self.order.append(rid)

    def _sorted(self):
        return sorted(self.order, key=lambda r: (self.reqs[r]["created_at"], r))

    def reconcile_one(self, rid, now):
        r = self.reqs[rid]
        if r["status"] == "accepted":
            return "accepted"
        if r["status"] in ("completed", "failed"):
            return r["status"]
        live = any(a["result"] is None and now <= a["expiry"] for a in r["attempts"])
        if live:
            return "processing"
        terminals = [(a["completed_at"], i, a["result"])
                     for i, a in enumerate(r["attempts"]) if a["result"] is not None]
        target = min(terminals)[2] if terminals else "failed"
        r["status"] = target
        for a in r["attempts"]:
            if a["result"] is None:
                a["result"] = "failed"
                a["completed_at"] = now
        if terminals:
            win = min(terminals)[1]
            for i, a in enumerate(r["attempts"]):
                if i != win and a["result"] == "completed":
                    a["result"] = "failed"
        r["token"] = None
        return target

    def batch(self, cursor_bid, limit, now):
        if cursor_bid is None:
            self.nb += 1
            bid = f"model-batch-{self.nb}"
            self.batches[bid] = dict(pos=-1, finished=False, items=[])
        else:
            bid = cursor_bid
        b = self.batches[bid]
        items = []
        ordered = self._sorted()
        while not b["finished"] and len(items) < limit:
            cand = None
            for idx, rid in enumerate(ordered):
                if idx <= b["pos"]:
                    continue
                cand = (idx, rid)
                break
            if cand is None:
                b["finished"] = True
                break
            idx, rid = cand
            if self.reqs[rid]["status"] == "accepted":
                b["pos"] = idx
                continue
            st = self.reconcile_one(rid, now)
            b["items"].append((rid, st))
            items.append({"request_id": rid, "status": st})
            b["pos"] = idx
        if not b["finished"]:
            rest = [r for i, r in enumerate(ordered) if i > b["pos"]]
            if not rest:
                b["finished"] = True
        return bid, (None if b["finished"] else "cursor"), b["finished"], items

